DO $$ DECLARE def text; BEGIN
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='save_delivery_route'; def=replace(def,'r.id=route_id','r.id=save_delivery_route.route_id'); def=replace(def,'AND d.status NOT IN (''Entregue'',''Cancelado''))','AND d.status NOT IN (''Entregue'',''Cancelado''))'); def=replace(def,'PERFORM 1 FROM public.delivery_orders WHERE id=ANY(stops) FOR UPDATE;','IF route_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.delivery_orders d WHERE d.route_id=save_delivery_route.route_id AND d.status NOT IN (''Aguardando preparo'',''Pronto para entrega'')) THEN RAISE EXCEPTION ''Rota já iniciada ou encerrada''; END IF; PERFORM 1 FROM public.delivery_orders WHERE id=ANY(stops) FOR UPDATE;'); EXECUTE def;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='update_delivery_status'; def=replace(def,'SELECT * INTO d FROM public.delivery_orders','PERFORM pg_advisory_xact_lock(742021); SELECT * INTO d FROM public.delivery_orders'); EXECUTE def;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='save_delivery_courier'; def=replace(def,'cid=coalesce(courier_id,gen_random_uuid());','PERFORM pg_advisory_xact_lock(742021); cid=coalesce(courier_id,gen_random_uuid());'); EXECUTE def;
SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='submit_pdv_operator_with_contact'; def=replace(def,'IF contact_name<>'''' OR phone_digits<>'''' THEN','IF request->>''type''=''Delivery'' THEN SELECT customer_id INTO contact_id FROM public.delivery_orders WHERE order_id=request->>''id''; END IF; IF (contact_name<>'''' OR phone_digits<>'''') AND request->>''type''<>''Delivery'' THEN'); EXECUTE def;
END $$;
INSERT INTO public.delivery_orders(order_id,customer_id,customer,phone,address,payment_method,cash_for,created_at,status)
SELECT o->>'id',nullif(o->>'customerId','')::uuid,coalesce(o->>'customer',''),coalesce(o->>'customerPhone',''),coalesce(o->'delivery'->'address','{}'),coalesce(o->'delivery'->>'paymentMethod','Pix'),coalesce(nullif(o->'delivery'->>'cashFor',''),'0')::numeric,to_timestamp((o->>'createdAt')::numeric/1000),CASE WHEN o->>'status'='cancelado' THEN 'Cancelado' WHEN o->>'status'='pronto' THEN 'Pronto para entrega' ELSE 'Aguardando preparo' END FROM public.pdv_state s,jsonb_array_elements(s.data->'orders') o WHERE s.id=1 AND o->>'type'='Delivery' ON CONFLICT(order_id) DO NOTHING;
COMMENT ON COLUMN public.delivery_routes.distance_meters IS 'Optional verified Maps provider output. NULL when maps are not configured; never estimate from address sorting.';